// ── Large models (4G board required) ───────────────────────────
Blockly.Msg.maixcam2_qwen_init = "init text chat model (Qwen2.5-1.5B)";
Blockly.Msg.maixcam2_qwen_init_TOOLTIP = "Load the chat model. Takes about 14 seconds, so keep it outside the loop. Only runs on the 4G board.";
Blockly.Msg.maixcam2_qwen_clear = "clear the chat memory";
Blockly.Msg.maixcam2_qwen_clear_TOOLTIP = "Forget everything said so far; the next question starts fresh. Put it right before the ask block and every question stands alone — the model will not remember your last one, but it will never run out of memory either.";
Blockly.Msg.maixcam2_qwen_stream = "stream onto canvas";
Blockly.Msg.maixcam2_qwen_stream_question = "ask the model";
Blockly.Msg.maixcam2_qwen_stream_TOOLTIP = "Ask a question; the answer appears character by character on the canvas. The program waits until the whole answer is done (6 to 20 seconds). The model remembers earlier rounds and stops answering once that memory is full — put a 'clear the chat memory' block just before this one to avoid it.";
Blockly.Msg.maixcam2_asr4g_start = "start recording";
Blockly.Msg.maixcam2_asr4g_start_TOOLTIP = "Start recording without blocking, so you can keep drawing and wait for the user to stop it. Needs the SenseVoice init block first.";
Blockly.Msg.maixcam2_asr4g_stop = "stop recording and recognise";
Blockly.Msg.maixcam2_asr4g_stop_TOOLTIP = "Stop recording and turn what was said into text (about one second). Read the result with the 'recognised text' block.";


