Blockly.Msg.maixcam2_kws_w_nihao = "ni hao (hello)";
Blockly.Msg.maixcam2_kws_w_kaideng = "kai deng (light on)";
Blockly.Msg.maixcam2_kws_w_guandeng = "guan deng (light off)";
Blockly.Msg.maixcam2_kws_w_kaishi = "kai shi (start)";
Blockly.Msg.maixcam2_kws_w_tingzhi = "ting zhi (stop)";
Blockly.Msg.maixcam2_kws_w_qianjin = "qian jin (forward)";
Blockly.Msg.maixcam2_kws_w_houtui = "hou tui (back)";
Blockly.Msg.maixcam2_kws_w_zuozhuan = "zuo zhuan (turn left)";
Blockly.Msg.maixcam2_kws_w_youzhuan = "you zhuan (turn right)";
Blockly.Msg.maixcam2_kws_add = "add keyword";
Blockly.Msg.maixcam2_kws_add_TOOLTIP = "Queue one keyword to listen for. Put these above Start listening for keywords; you can use several.";
Blockly.Msg.maixcam2_kws_init = "start listening for keywords, sensitivity";
Blockly.Msg.maixcam2_kws_init_TOOLTIP = "Open the mic and register the keywords added above. Takes about 2 seconds. Sensitivity is the trigger threshold: lower fires more easily but also misfires more. Start at 0.5, then use the similarity block to see real values and tune.";
Blockly.Msg.maixcam2_kws_heard = "heard keyword";
Blockly.Msg.maixcam2_kws_heard_TOOLTIP = "Whether this keyword was heard in the last frame. True only at the moment it crosses the sensitivity, so it will not fire repeatedly. Run Process one frame of speech first.";
Blockly.Msg.maixcam2_kws_score_pre = "similarity of keyword";
Blockly.Msg.maixcam2_kws_score_post = "";
Blockly.Msg.maixcam2_kws_score_TOOLTIP = "Similarity of this keyword in the last frame, 0 to 1. Above 0.9 when recognised, 0 when not heard. Use it to pick the sensitivity.";
Blockly.Msg.maixcam2_kws_result = "keyword just heard";
Blockly.Msg.maixcam2_kws_result_TOOLTIP = "The pinyin of the keyword that was just heard (e.g. ni3 hao3), or an empty string otherwise. Compare it with text: 'if keyword just heard = zai4 jian4'. Works for both preset and custom keywords. It only has a value at the moment the word is heard, so saying it once triggers once. Place it after 'process one speech frame'.";
Blockly.Msg.maixcam2_digit_init = "start listening for digits";
Blockly.Msg.maixcam2_digit_init_TOOLTIP = "Open the mic and start recognising spoken Chinese digits. Takes about 2 seconds. Keep it outside the loop.";
Blockly.Msg.maixcam2_digit_text = "digits heard";
Blockly.Msg.maixcam2_digit_text_TOOLTIP = "Digits spoken in the last 4 seconds, e.g. 12345. Older ones drop off on their own. Run Process one frame of speech first.";
Blockly.Msg.maixcam2_lvcsr_init = "start speech recognition";
Blockly.Msg.maixcam2_lvcsr_init_TOOLTIP = "Open the mic and load the language model. Takes about 2 seconds. Keep it outside the loop. This is a small model: short phrases and digits are accurate, long sentences drift.";
Blockly.Msg.maixcam2_lvcsr_text = "last sentence recognised";
Blockly.Msg.maixcam2_lvcsr_text_TOOLTIP = "The last finished phrase. Pauses split sentences automatically. Run Process one frame of speech first.";
Blockly.Msg.maixcam2_lvcsr_all = "all text recognised";
Blockly.Msg.maixcam2_lvcsr_all_TOOLTIP = "Everything recognised so far; commas are short pauses, periods long ones. It keeps growing, use Clear recognition result to reset.";
Blockly.Msg.maixcam2_speech_run = "process one frame of speech";
Blockly.Msg.maixcam2_speech_run_TOOLTIP = "Listen for 0.77 s and recognise once. The program waits here, so a loop containing this block runs about 1.3 times a second. All three recognisers need it to advance.";
Blockly.Msg.maixcam2_speech_clear = "clear recognition result";
Blockly.Msg.maixcam2_speech_clear_TOOLTIP = "Reset the recognised text and start listening fresh.";

