Blockly.Msg.maixcam2_whisper_text = "text recognised by Whisper";
Blockly.Msg.maixcam2_whisper_text_TOOLTIP = "The text from the last recording.";

// ── Large models (4G required) > text-to-image / image-to-image ──
Blockly.Msg.maixcam2_sd_init = "init text-to-image model (lcm-lora-sdv1-5)";
Blockly.Msg.maixcam2_sd_init_TOOLTIP = "Load the image generation model. Takes over a minute (55 seconds just to load torch) and the program freezes meanwhile, so keep it outside the loop. After that each image takes about 2 seconds. 4G board only.";
Blockly.Msg.maixcam2_sd_draw = "draw";
Blockly.Msg.maixcam2_sd_draw_to = "onto canvas";
Blockly.Msg.maixcam2_sd_seed = "seed";
Blockly.Msg.maixcam2_sd_draw_TOOLTIP = "Generate a picture from a text description, about 2 seconds. English only, up to 77 tokens - Chinese will not error but will not draw correctly. The picture is 256x256 and is drawn at the top-left of the canvas. The same words plus the same seed always give the same picture.";
Blockly.Msg.maixcam2_sd_redraw = "redraw canvas";
Blockly.Msg.maixcam2_sd_redraw_to = "as";
Blockly.Msg.maixcam2_sd_redraw_TOOLTIP = "Use what is on the canvas as the starting picture and redraw it from the description, about 2 seconds. English only. The result is also 256x256, drawn at the top-left.";

// ── LLM > audio file in, audio file out (matches the old online ASR / TTS) ──
Blockly.Msg.maixcam2_asr_file = "recognise audio file";
Blockly.Msg.maixcam2_asr_file_TOOLTIP = "Turn an audio file on the board into text; read the result with 'text recognised'. The file must be a wav at 16000 Hz, mono, 16-bit - a wrong format does not error, it just recognises badly. The path is a path on the board, not on your computer.";
Blockly.Msg.maixcam2_tts_save = "save";
Blockly.Msg.maixcam2_tts_save_to = "as audio file";
Blockly.Msg.maixcam2_tts_save_TOOLTIP = "Synthesise the text and write it to a wav file (44100 Hz, mono) instead of playing it. Use the 'play audio file' block to play it. The only difference from 'say' is whether a file is kept.";
Blockly.Msg.maixcam2_kws_add_custom = "add custom keyword";
Blockly.Msg.maixcam2_kws_add_custom_TOOLTIP = "Type your own keyword for the board to listen for. It takes pinyin, not Chinese characters - one lowercase syllable per character with a tone digit, separated by spaces, e.g. ni3 hao3 for 你好. Like 'add keyword' it must go above 'start listening for keywords', and the two can be mixed.";

// pi2 板載 IMU（maixcam2_imu.js，合約 tools/e2e/contracts/imu-contract.md）
Blockly.Msg.maixcam2_imu_calibrate = "calibrate gyroscope";
Blockly.Msg.maixcam2_imu_calibrate_TOOLTIP = "Keep the board flat and still: measures the gyroscope offset for 2 seconds and saves it on the board, loaded automatically afterwards. Only needed the first time, or when the heading seems off.";
Blockly.Msg.maixcam2_imu_heading = "heading (degrees turned)";
Blockly.Msg.maixcam2_imu_heading_TOOLTIP = "Degrees turned since the last \"reset heading\": right is positive, left is negative; keeps counting past a full turn (e.g. 720). Run \"calibrate gyroscope\" once first.";
Blockly.Msg.maixcam2_imu_heading_reset = "reset heading";
Blockly.Msg.maixcam2_imu_heading_reset_TOOLTIP = "Treat the current direction as 0 degrees. Reset before a turn, then watch the heading.";
Blockly.Msg.maixcam2_imu_err_not_calibrated = "The gyroscope on this board has not been calibrated yet. Run the \"calibrate gyroscope\" block once first (board flat and still).";
Blockly.Msg.maixcam2_imu_err_moved = "The board moved during calibration. Keep it still and run it again.";
Blockly.Msg.maixcam2_imu_msg_calibrating = "Calibrating, do not move the board (2 seconds)...";
Blockly.Msg.maixcam2_imu_msg_calibrated = "Calibration done, offset saved to ";
